add_filter( 'woocommerce_checkout_fields', 'perfectpixel_default_billing_city', 9999 );

function perfectpixel_default_billing_city( $fields ) {
	$field = 'billing_city';
	if ( isset( $fields['billing'][ $field ] ) ) {
		$fields['billing'][ $field ]['default'] = '{{default_city}}';
	}
	return $fields;
}
